create table if not exists public.product_categories(category_id bigint generated always as identity primary key,category_name text not null,parent_id bigint references public.product_categories(category_id) on delete set null,unique(category_name,parent_id));
create table if not exists public.product_brands(brand_id bigint generated always as identity primary key,brand_name text not null unique);
create table if not exists public.product_groups(group_id bigint generated always as identity primary key,group_name text not null unique);
create table if not exists public.item_types(item_type_id bigint generated always as identity primary key,type_code text not null unique,type_name text not null,is_inventory boolean not null default true,is_assembled boolean not null default false);
create table if not exists public.products(product_id bigint generated always as identity primary key,item_code text not null unique,display_name text not null,item_type_id bigint not null references public.item_types(item_type_id),category_id bigint references public.product_categories(category_id),brand_id bigint references public.product_brands(brand_id),uom_id bigint not null references public.uom(uom_id),tax_code_id bigint references public.tax_codes(tax_code_id),purchase_cost numeric(24,6) not null default 0 check(purchase_cost>=0),sales_price numeric(24,6) not null default 0 check(sales_price>=0),is_active boolean not null default true);
create table if not exists public.product_subsidiaries(id bigint generated always as identity primary key,product_id bigint not null references public.products(product_id) on delete cascade,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id) on delete cascade,is_active boolean not null default true,unique(product_id,subsidiary_id));
create table if not exists public.product_supplier(id bigint generated always as identity primary key,product_id bigint not null references public.products(product_id) on delete cascade,supplier_id bigint not null references public.suppliers(supplier_id) on delete cascade,supplier_part_number text,is_preferred boolean not null default false,unique(product_id,supplier_id));
create table if not exists public.product_images(image_id bigint generated always as identity primary key,product_id bigint not null references public.products(product_id) on delete cascade,image_url text not null,is_primary boolean not null default false);
create table if not exists public.barcode(barcode_id bigint generated always as identity primary key,product_id bigint not null references public.products(product_id) on delete cascade,barcode_value text not null unique,barcode_type text not null);
create table if not exists public.warehouse_locations(warehouse_location_id bigint generated always as identity primary key,location_id bigint not null references public.locations(location_id) on delete cascade,zone_name text not null,aisle text,rack text,unique(location_id,zone_name,aisle,rack));
create table if not exists public.bins(bin_id bigint generated always as identity primary key,bin_code text not null,warehouse_location_id bigint not null references public.warehouse_locations(warehouse_location_id) on delete cascade,max_capacity numeric(24,6) check(max_capacity>=0),unique(bin_code,warehouse_location_id));
create table if not exists public.item_location_configuration(id bigint generated always as identity primary key,product_id bigint not null references public.products(product_id) on delete cascade,location_id bigint not null references public.locations(location_id) on delete cascade,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id) on delete cascade,preferred_bin_id bigint references public.bins(bin_id),safety_stock numeric(24,6) not null default 0 check(safety_stock>=0),reorder_point numeric(24,6) not null default 0 check(reorder_point>=0),average_cost numeric(24,6) not null default 0 check(average_cost>=0),unique(product_id,location_id,subsidiary_id));
create table if not exists public.stock(stock_id bigint generated always as identity primary key,product_id bigint not null references public.products(product_id) on delete cascade,location_id bigint not null references public.locations(location_id) on delete cascade,bin_id bigint references public.bins(bin_id),quantity_on_hand numeric(24,6) not null default 0,quantity_committed numeric(24,6) not null default 0 check(quantity_committed>=0),quantity_available numeric(24,6) not null default 0,unique(product_id,location_id,bin_id));
create table if not exists public.stock_lots(lot_id bigint generated always as identity primary key,lot_number text not null,product_id bigint not null references public.products(product_id) on delete cascade,location_id bigint not null references public.locations(location_id) on delete cascade,expiration_date date,quantity numeric(24,6) not null default 0,unique(lot_number,product_id,location_id));
create table if not exists public.stock_serials(serial_id bigint generated always as identity primary key,serial_number text not null unique,product_id bigint not null references public.products(product_id) on delete cascade,location_id bigint not null references public.locations(location_id) on delete cascade,lot_id bigint references public.stock_lots(lot_id) on delete set null,status text not null);
do $$declare t text;begin foreach t in array array['product_categories','product_brands','product_groups','item_types','products','product_subsidiaries','product_supplier','product_images','barcode','warehouse_locations','bins','item_location_configuration','stock','stock_lots','stock_serials']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "inventory_select" on public.%I',t);execute format('drop policy if exists "inventory_insert" on public.%I',t);execute format('drop policy if exists "inventory_update" on public.%I',t);execute format('drop policy if exists "inventory_delete" on public.%I',t);execute format('create policy "inventory_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "inventory_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "inventory_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "inventory_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
